amount = 0
line = contract.benefit_deduction_ids.filtered(lambda x: x.rule_id.code == 'PEM')
if line:
    if line.state == 'progress':
        if line.periodicity == 'infinite':
            if line.schedule_pay == 'bi-weekly':
                if line.apply_in == 'first':
                    if payslip.date_from.day == 1:
                        amount = line.get_fee_amount()

                if line.apply_in == 'second':
                    if payslip.date_from.day == 16:
                        amount = line.get_fee_amount()

                if line.apply_in == 'both':
                    amount = line.get_fee_amount()
            else:
                amount = line.get_fee_amount()
        else:
            if payslip.date_from >= line.start_date:
                if line.fee_numbers_apply < line.fee_numbers:
                    if line.schedule_pay == 'bi-weekly':
                        if line.apply_in == 'first':
                            if payslip.date_from.day == 1:
                                amount = line.get_fee_amount()

                        if line.apply_in == 'second':
